style.css:
@-moz-document domain("youtube.com") {
/* ? General Background */
   body, ytd-app {
    background: url("https://i.pinimg.com/736x/55/7b/fa/557bfaf224030175be18e854477e99bd.jpg") repeat fixed center !important;
    background-size: cover;
    color: #ffe4e1;
    font-family: "Impact", "Arial Black", cursive !important;
  }

  /* ? Top Bar (Header) Background Image */
  #container.ytd-masthead, ytd-masthead {
    background: url("https://i.pinimg.com/736x/23/c8/06/23c806ca52712371a7f72ede54c5b02a.jpg") center center no-repeat !important;
    background-size: cover !important;
    color: white !important;
    border-bottom: 3px solid gold !important;
  }

  #container.ytd-masthead * {
    color: white !important;
    text-shadow: 0 0 5px black;
  }

  /* ? Sidebar Background Image */
  ytd-guide-renderer {
    background: url("data:image/png;base64,") center top no-repeat !important;
    background-size: cover !important;
    border-right: 3px solid gold !important;
    color: white !important;
  }

  ytd-guide-renderer * {
    color: white !important;
    text-shadow: 0 0 3px black;
    position: relative;
    z-index: 1;
  }

  ytd-guide-renderer::before {
    content: "";
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.3); /* optional dark overlay */
    z-index: 0;
  }

  /* ? Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }
  ::-webkit-scrollbar-thumb {
    background: gold;
    border-radius: 5px;
  }

  /* ? Keep the rest of your mamba glam style below (buttons, borders, titles, etc.) */
}
